const METROS = [{"name": "Metro Vancouver", "prov": "BC", "cd": "5915", "units": 129351, "units20": 115949, "rent": 1970, "vac": 3.7, "turn": 11.6, "condo": "33.9%", "note": "The largest and slowest-turning market. 107,192 condos are in the rental pool, close to the number of purpose-built units."}, {"name": "Victoria", "prov": "BC", "cd": "5917", "units": 34759, "units20": 28206, "rent": 1812, "vac": 3.3, "turn": 18.6, "condo": "27.1%", "note": "Purpose-built stock up 23% since 2020. Older stratas in the Capital region were due a depreciation report by 1 July 2026."}, {"name": "Kelowna", "prov": "BC", "cd": "5935", "units": 10680, "units20": 7423, "rent": 1906, "vac": 6.3, "turn": 28.7, "condo": "31.3%", "note": "The highest vacancy of the ten after its stock grew 44% since 2020. A leasing market, not a waiting list."}, {"name": "Abbotsford–Mission", "prov": "BC", "cd": "5909", "units": 5946, "units20": 4859, "rent": 1447, "vac": 3.1, "turn": 9.4, "condo": null, "note": "Low turnover and a small purpose-built stock. In the Fraser Valley district most rentals are suites, houses and condos."}, {"name": "Chilliwack", "prov": "BC", "cd": "5909", "units": 4166, "units20": 3412, "rent": 1386, "vac": 3.0, "turn": 10.6, "condo": null, "note": "Same district as Abbotsford–Mission. Purpose-built stock up 22% since 2020."}, {"name": "Nanaimo", "prov": "BC", "cd": "5921", "units": 5891, "units20": 4316, "rent": 1688, "vac": 2.2, "turn": 23.5, "condo": null, "note": "The tightest vacancy of the ten, with stock up 36% since 2020."}, {"name": "Calgary", "prov": "AB", "cd": "4806", "units": 67980, "units20": 45882, "rent": 1775, "vac": 4.9, "turn": 24.7, "condo": "34.7%", "note": "The fastest-growing stock: up 48% since 2020, with 9,841 rental starts in 2025."}, {"name": "Edmonton", "prov": "AB", "cd": "4811", "units": 102108, "units20": 80933, "rent": 1493, "vac": 3.8, "turn": 27.8, "condo": "36.6%", "note": "The largest purpose-built market outside Vancouver, and 8,922 rental starts in 2025."}, {"name": "Red Deer", "prov": "AB", "cd": "4808", "units": 7152, "units20": 6921, "rent": 1379, "vac": 3.2, "turn": 21.3, "condo": null, "note": "A stable stock (up 3% since 2020). Lower rents mean thinner fees per unit."}, {"name": "Lethbridge", "prov": "AB", "cd": "4802", "units": 4543, "units20": 3965, "rent": 1549, "vac": 4.2, "turn": 37.8, "condo": null, "note": "The highest turnover in either province: more than a third of units changed tenants in a year."}];
const fmt = new Intl.NumberFormat('en-CA');
const money = v => v >= 1e9 ? '$' + (v/1e9).toFixed(v >= 1e10 ? 1 : 2) + 'B' : v >= 1e6 ? '$' + (v/1e6).toFixed(v >= 1e8 ? 0 : 1) + 'M' : '$' + fmt.format(Math.round(v/1e3)) + 'k';
const M = {
  rent_paid: {name:'Rent paid per year', f: money},
  fee_pool_base: {name:'Management fee pool per year (base case)', f: money},
  renter_hh_2025: {name:'Renter households, 2025', f: v => fmt.format(Math.round(v))},
  pm_firms_employer: {name:'Property-manager businesses with employees', f: v => fmt.format(Math.round(v))},
};
const BINS = [15, 20, 25, 30, 35, 40];
const shade = p => { let i = 0; while (i < BINS.length && p >= BINS[i]) i++; return `var(--s${i+1})`; };
const ns = 'http://www.w3.org/2000/svg';
const el = (t, a = {}, p) => { const e = document.createElementNS(ns, t); for (const k in a) { if ((k === 'fill' || k === 'stroke') && String(a[k]).includes('var(')) e.style[k] = a[k]; else e.setAttribute(k, a[k]); } if (p) p.appendChild(e); return e; };
const byCd = Object.fromEntries(DATA.districts.map(d => [d.cduid, d]));

/* ---------- map ---------- */
const svg = document.getElementById("mapsvg");
const gCd = el('g', {}, svg), gPr = el('g', {}, svg), gSp = el('g', {}, svg), gLb = el('g', {}, svg);
for (const [id, d] of Object.entries(DATA.paths)) {
  if (id.startsWith('cd-')) {
    const cd = id.slice(3), r = byCd[cd];
    const p = el('path', {d, class:'cd', id, 'data-cd':cd, tabindex:'0', 'aria-label': r ? r.label : cd}, gCd); p.style.fill = r ? shade(r.renter_pct) : 'var(--s1)';
  } else el('path', {d, class:'pr'}, gPr);
}
el('text', {x:300, y:470, class:'provlbl'}, svg).textContent = 'British Columbia';
el('text', {x:810, y:330, class:'provlbl'}, svg).textContent = 'Alberta';
let metric = 'rent_paid', sel = '5915';
function drawSpikes(){
  gSp.replaceChildren(); gLb.replaceChildren();
  const max = Math.max(...DATA.districts.map(d => d[metric]));
  const H = 300, W = 12;
  const ds = [...DATA.districts].sort((a, b) => a.sy - b.sy);
  for (const d of ds) {
    const h = Math.max(1.5, d[metric] / max * H);
    el('path', {d:`M${d.sx - W/2},${d.sy}L${d.sx},${d.sy - h}L${d.sx + W/2},${d.sy}Z`, class:'spike' + (d.cduid === sel ? ' hot' : ''), 'data-cd':d.cduid}, gSp);
  }
  const top = [...DATA.districts].sort((a, b) => b[metric] - a[metric]).slice(0, 5);
  const placed = [];
  for (const d of top) {
    const h = Math.max(1.5, d[metric] / max * H);
    let x = d.sx + 10, y = d.sy - h + 4;
    for (const q of placed) if (Math.abs(q[0] - x) < 150 && Math.abs(q[1] - y) < 34) y = q[1] + 36;
    placed.push([x, y]);
    const t = el('text', {x, y, class:'slabel'}, gLb);
    el('tspan', {x, dy:0}, t).textContent = d.label;
    const v = el('tspan', {x, dy:15, class:'v'}, t); v.textContent = M[metric].f(d[metric]);
  }
}
const panel = document.getElementById('dpanel');
function showPanel(cd){
  const d = byCd[cd]; if (!d) return;
  sel = cd;
  document.querySelectorAll('#mapsvg .cd').forEach(p => p.classList.toggle('hot', p.dataset.cd === cd));
  document.querySelectorAll('#mapsvg .spike').forEach(p => p.classList.toggle('hot', p.dataset.cd === cd));
  panel.innerHTML = `<span class="eyebrow">${d.prov === 'BC' ? 'British Columbia' : 'Alberta'} · ${d.cduid}</span><h4>${d.label}</h4>
  <dl><dt>Renter households (2025)</dt><dd>${fmt.format(d.renter_hh_2025)}</dd>
  <dt>Share of households renting</dt><dd>${d.renter_pct.toFixed(1)}%</dd>
  <dt>Average rent</dt><dd>$${fmt.format(d.avg_rent)}</dd>
  <dt>Rent paid per year</dt><dd>${money(d.rent_paid)}</dd>
  <dt>Purpose-built rental units</dt><dd>${d.purpose_built ? fmt.format(d.purpose_built) : '—'}</dd>
  <dt>Tenant turnover</dt><dd>${(d.turnover * 100).toFixed(1)}%</dd>
  <dt>Condo dwellings</dt><dd>${fmt.format(d.strata_units)}</dd>
  <dt>PM businesses (employer)</dt><dd>${fmt.format(d.pm_firms_employer)}</dd>
  <dt>Fee pool, base</dt><dd>${money(d.fee_pool_base)}</dd>
  <dt>Fee pool, range</dt><dd>${money(d.fee_pool_low)} – ${money(d.fee_pool_high)}</dd>
  <dt>Population growth 2021–25</dt><dd>${d.pop_growth_pct.toFixed(1)}%</dd></dl>
  <p class="src">Rent: ${d.rent_src}. Fee pool and managed share are assumption ranges (see Method &amp; sources).</p>`;
}
const tip = document.getElementById('tip'), box = document.getElementById('mapbox');
gCd.addEventListener('pointermove', e => {
  const cd = e.target.dataset && e.target.dataset.cd; if (!cd) return;
  const d = byCd[cd], r = box.getBoundingClientRect();
  tip.innerHTML = `<b>${d.label}</b>${M[metric].name}: ${M[metric].f(d[metric])}<br>Renters: ${d.renter_pct.toFixed(1)}% of households`;
  tip.hidden = false;
  const x = e.clientX - r.left + 14, y = e.clientY - r.top + 14;
  tip.style.left = Math.min(x, r.width - 250) + 'px'; tip.style.top = Math.min(y, r.height - 80) + 'px';
});
gCd.addEventListener('pointerleave', () => tip.hidden = true);
gCd.addEventListener('click', e => { const cd = e.target.dataset && e.target.dataset.cd; if (cd) showPanel(cd); });
gCd.addEventListener('keydown', e => { if ((e.key === 'Enter' || e.key === ' ') && e.target.dataset.cd) { e.preventDefault(); showPanel(e.target.dataset.cd); } });
document.getElementById('metricSeg').addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  metric = b.dataset.m;
  document.querySelectorAll('#metricSeg button').forEach(x => x.setAttribute('aria-pressed', x === b));
  drawSpikes(); showPanel(sel); legend();
});
function legend(){
  const L = document.getElementById('mapLegend');
  const labels = ['<15%', '15–20', '20–25', '25–30', '30–35', '35–40', '40%+'];
  L.innerHTML = `<span><svg width="12" height="16" viewBox="0 0 12 16" style="vertical-align:-3px;margin-right:6px"><path d="M1,15L6,1L11,15Z" fill="var(--spike)" fill-opacity=".7" stroke="var(--spike-edge)"/></svg>Spike height: ${M[metric].name.toLowerCase()}</span>
  <span>Shading: share of households renting (2021)</span><span class="ramp">${labels.map((l, i) => `<i style="background:var(--s${i+1})" title="${l}"></i>`).join('')}</span><span class="muted">${labels[0]} → ${labels[6]}</span>`;
}
drawSpikes(); showPanel(sel); legend();

/* ---------- bar charts ---------- */
function hbar(id, rows, opt){
  const s = document.getElementById(id); s.replaceChildren();
  const W = 520, lw = opt.lw || 130, rh = 24, top = 6, H = top + rows.length * rh + 22;
  s.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const max = opt.max || Math.max(...rows.map(r => r.v)), x = v => lw + v / max * (W - lw - 54);
  for (const t of opt.ticks) { el('line', {x1:x(t), x2:x(t), y1:top, y2:H - 18, class:'grid'}, s); el('text', {x:x(t), y:H - 4, class:'ax', 'text-anchor':'middle'}, s).textContent = opt.tf(t); }
  rows.forEach((r, i) => {
    const y = top + i * rh, g = el('g', {}, s);
    el('title', {}, g).textContent = `${r.k}: ${opt.vf(r.v)}`;
    el('rect', {x:0, y, width:W, height:rh, class:'hit'}, g);
    el('text', {x:lw - 8, y:y + rh/2 + 4, class:'lbl', 'text-anchor':'end'}, g).textContent = r.k;
    const w = Math.max(2, x(r.v) - lw);
    el('path', {d:`M${lw},${y+5}h${w-4}a4,4 0 0 1 4,4v${rh-18}a4,4 0 0 1 -4,4h-${w-4}Z`, fill: r.c || opt.c}, g);
    el('text', {x:lw + w + 6, y:y + rh/2 + 4, class:'val'}, g).textContent = opt.vf(r.v);
  });
  el('line', {x1:lw, x2:lw, y1:top, y2:H - 18, class:'base'}, s);
}
const byTurn = [...METROS].sort((a, b) => b.turn - a.turn);
hbar('turnChart', byTurn.map(m => ({k:m.name, v:m.turn, c: m.prov === 'AB' ? 'var(--p-ab)' : 'var(--p-bc)'})), {ticks:[0,10,20,30,40], max:40, tf:t => t + '%', vf:v => v.toFixed(1) + '%', lw:130});
const byGrow = [...METROS].map(m => ({...m, g:(m.units / m.units20 - 1) * 100})).sort((a, b) => b.g - a.g);
hbar('growChart', byGrow.map(m => ({k:m.name, v:m.g, c: m.prov === 'AB' ? 'var(--p-ab)' : 'var(--p-bc)'})), {ticks:[0,10,20,30,40,50], max:50, tf:t => t + '%', vf:v => '+' + v.toFixed(0) + '%', lw:130});
const SIZE = {"BC": [["1–4", 580], ["5–9", 155], ["10–19", 106], ["20–49", 86], ["50–99", 30], ["100+", 19]], "AB": [["1–4", 352], ["5–9", 135], ["10–19", 84], ["20–49", 74], ["50–99", 18], ["100+", 9]]};
for (const [id, p] of [['sizeBC', 'BC'], ['sizeAB', 'AB']]) {
  const tot = SIZE[p].reduce((a, r) => a + r[1], 0);
  hbar(id, SIZE[p].map(r => ({k:r[0], v:r[1] / tot * 100, n:r[1]})), {ticks:[0,20,40,60], max:60, tf:t => t + '%', vf:v => v.toFixed(1) + '%', c: p === 'BC' ? 'var(--p-bc)' : 'var(--p-ab)', lw:90});
}
for (const id of ['turnChart', 'growChart']) {
  const lg = document.createElement('div'); lg.className = 'legend'; lg.style.marginTop = '8px';
  lg.innerHTML = '<span><i class="sw" style="background:var(--p-bc)"></i>British Columbia</span><span><i class="sw" style="background:var(--p-ab)"></i>Alberta</span>';
  document.getElementById(id).after(lg);
}

/* ---------- AI chart ---------- */
(function(){
  const s = document.getElementById('aiChart');
  const S = [{k:'British Columbia', c:'var(--p-bc)', v:[3.3,3.1,31.0], q:['A','A','D']}, {k:'Alberta', c:'var(--p-ab)', v:[11.6,8.2,18.9], q:['C','C','C']}, {k:'Canada', c:'var(--p-ca)', v:[8.1,11.8,18.7], q:['A','B','B'], dash:true}];
  const yrs = [2024, 2025, 2026], W = 520, H = 280, l = 40, r = 120, t = 14, b = 30;
  s.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const x = i => l + i * (W - l - r) / 2, y = v => t + (1 - v / 35) * (H - t - b);
  for (const v of [0, 10, 20, 30]) { el('line', {x1:l, x2:W - r, y1:y(v), y2:y(v), class: v ? 'grid' : 'base'}, s); el('text', {x:l - 8, y:y(v) + 4, class:'ax', 'text-anchor':'end'}, s).textContent = v + '%'; }
  yrs.forEach((yr, i) => el('text', {x:x(i), y:H - 8, class:'ax', 'text-anchor':'middle'}, s).textContent = yr);
  const ends = [];
  for (const se of S) {
    el('path', {d: se.v.map((v, i) => `${i ? 'L' : 'M'}${x(i)},${y(v)}`).join(''), fill:'none', stroke:se.c, 'stroke-width':2, 'stroke-dasharray': se.dash ? '5 4' : 'none'}, s);
    se.v.forEach((v, i) => { const g = el('g', {}, s); el('title', {}, g).textContent = `${se.k} ${yrs[i]}: ${v}% (quality ${se.q[i]})`; el('circle', {cx:x(i), cy:y(v), r:12, class:'hit'}, g); el('circle', {cx:x(i), cy:y(v), r:4.5, fill:se.c, stroke:'var(--card)', 'stroke-width':2}, g); });
    ends.push({se, y:y(se.v[2])});
  }
  ends.sort((a, b) => a.y - b.y);
  for (let i = 1; i < ends.length; i++) if (ends[i].y - ends[i-1].y < 34) ends[i].y = ends[i-1].y + 34;
  for (const e of ends) { const tx = el('text', {x:x(2) + 12, y:e.y + 4, class:'lbl'}, s); el('tspan', {}, tx).textContent = e.se.k; const v = el('tspan', {x:x(2) + 12, dy:14, class:'val'}, tx); v.textContent = `${e.se.v[2]}% · grade ${e.se.q[2]}`; }
  document.getElementById('aiLegend').innerHTML = S.map(se => `<span><i class="sw" style="background:${se.c}"></i>${se.k}</span>`).join('');
})();
